<template><WorkspaceLayout role="USER"><p class="eyebrow">订单记录</p><h1 class="page-title">每一次服务，清晰可见。</h1><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="order-list"><article v-for="order in orders" :key="order.id" class="surface order-card"><div><span class="eyebrow">订单 #{{ order.id }}</span><h2>{{ order.item_name_snapshot }}</h2><p class="muted">{{ formatTime(order.start_at) }} · ¥{{ order.payable_amount }}</p></div><div class="order-actions"><span class="status">{{ statusName(order.status) }}</span><button class="text-button" @click="show(order.id)">查看详情</button><button v-if="order.status === 'WAITING_CONFIRMATION'" class="primary" @click="act(order.id,'confirm')">确认完成</button><button v-if="order.status === 'INTERRUPTED'" class="primary" @click="openFees(order.id)">核对费用</button><button v-if="order.status === 'COMPLETED' || order.status==='ABNORMAL_CLOSED'" class="primary" @click="openSettlement(order.id)">查看结算</button><button v-if="order.status === 'COMPLETED'" class="text-button" @click="openReview(order.id)">评价</button><button v-if="order.status === 'COMPLETED'" class="text-button" @click="openDispute(order.id)">服务争议</button><button v-if="['WAITING_ASSIGNMENT','WAITING_ACCEPTANCE','WAITING_SERVICE'].includes(order.status)" class="text-button" @click="act(order.id,'cancel')">取消预约</button></div></article><div v-if="!orders.length && !error" class="empty">暂无订单，您可以先预约服务。</div></div>
<el-dialog v-model="detailOpen" title="订单详情" width="min(94vw, 600px)"><div v-if="detail" class="detail"><p><strong>服务</strong>{{ detail.item_name_snapshot }}</p><p><strong>状态</strong>{{ statusName(detail.status) }}</p><p><strong>原预约时间</strong>{{ formatTime(detail.start_at) }} 至 {{ formatTime(detail.end_at) }}</p><p><strong>服务地址</strong>{{ detail.street_name_snapshot }} {{ detail.address_snapshot }}</p><p><strong>服务规则</strong>{{ detail.rule_snapshot }}</p><p><strong>应付金额</strong>¥{{ detail.payable_amount }}</p><div v-for="plan in supplements" :key="plan.id" class="attempt"><strong>补服务 · {{ supplementLabel(plan.status) }}</strong><span>{{ formatTime(plan.start_at) }} 至 {{ formatTime(plan.end_at) }}</span><span>{{ plan.reason }}</span></div></div></el-dialog>
<el-dialog v-model="settlementOpen" title="订单结算" width="min(94vw, 620px)"><div v-if="settlement"><p>应付金额：<strong>¥{{ settlement.settlement.amount }}</strong></p><p>结算状态：{{ settlementLabel(settlement.settlement.status) }}</p><p>结算方式：{{ settlement.settlement.method === 'SIMULATED' ? '模拟支付' : settlement.settlement.method === 'OFFLINE' ? '线下登记' : settlement.settlement.method==='WAIVED' ? '免收费用' : '未选择' }}</p><div v-for="attempt in settlement.attempts" :key="attempt.attempt_ref" class="attempt"><strong>尝试标识：{{ attempt.attempt_ref }}</strong><span>状态：{{ attemptLabel(attempt.remote_status) }}</span><p v-if="settlement.settlement.status !== 'SETTLED'" class="muted">请在独立模拟支付控制台登记同一标识、订单号、版本和金额，再设置测试结果，最后点击同步。此操作不涉及真实资金。</p><p>订单号：{{ settlementOrderId }} · 版本：{{ attempt.settlement_version }} · 金额：¥{{ attempt.amount }}</p></div><div class="settlement-actions"><button v-if="['WAITING_METHOD','FAILED'].includes(settlement.settlement.status)" class="primary" @click="createAttempt">创建模拟支付尝试</button><button v-if="settlement.attempts.length && settlement.settlement.status !== 'SETTLED'" class="text-button" @click="sync">查询并同步交易</button></div></div></el-dialog>
<el-dialog v-model="reviewOpen" title="评价服务" width="min(94vw, 520px)"><el-form label-position="top"><el-form-item label="评分"><el-rate v-model="reviewStars" /></el-form-item><el-form-item label="评价内容（选填）"><el-input v-model="reviewContent" type="textarea" maxlength="1000" /></el-form-item></el-form><template #footer><button class="primary" @click="submitReview">提交评价</button></template></el-dialog>
<el-dialog v-model="feesOpen" title="异常费用核对" width="min(94vw, 580px)"><p>订单 #{{ feesOrderId }} 中断后由管理员核实费用。有权用户确认后，金额才会生效并结案。</p><div v-for="fee in fees" :key="fee.id" class="attempt"><strong>原金额 ¥{{ fee.original_amount }} → 建议金额 ¥{{ fee.proposed_amount }}</strong><p>{{ fee.reason }}</p><span>状态：{{ feeLabel(fee.status) }}</span><div v-if="fee.status==='PENDING'" class="settlement-actions"><button class="primary" @click="decideFee(fee.id,true)">同意费用</button><button class="text-button" @click="decideFee(fee.id,false)">不同意</button></div></div><div v-if="!fees.length" class="empty">管理员尚未提交费用提案，请等待异常协调。</div></el-dialog>
</WorkspaceLayout></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import WorkspaceLayout from '../../layouts/WorkspaceLayout.vue'
import { api } from '../../api/client'
type Order = { id:number; item_name_snapshot:string; status:string; start_at:string; end_at:string; payable_amount:number; street_name_snapshot:string; address_snapshot:string; rule_snapshot:string }
type Settlement = {settlement:{amount:number;status:string;method:string|null};attempts:{attempt_ref:string;remote_status:string;settlement_version:number;amount:number}[]}
const orders = ref<Order[]>([]), detail = ref<Order | null>(null), detailOpen = ref(false), error = ref('')
const settlement = ref<Settlement|null>(null),settlementOpen=ref(false),settlementOrderId=ref(0)
const reviewOpen=ref(false),reviewOrderId=ref(0),reviewStars=ref(5),reviewContent=ref('')
const labels: Record<string,string> = { WAITING_ASSIGNMENT:'待派单', WAITING_ACCEPTANCE:'待接单', WAITING_SERVICE:'待服务', IN_SERVICE:'服务中', WAITING_CONFIRMATION:'待确认', COMPLETED:'已完成', CANCELLED:'已取消',INTERRUPTED:'服务中断',ABNORMAL_CLOSED:'异常结案' }
type Fee={id:number;original_amount:number;proposed_amount:number;reason:string;status:string}
const fees=ref<Fee[]>([]),feesOpen=ref(false),feesOrderId=ref(0)
type Supplement={id:number;start_at:string;end_at:string;reason:string;status:string}
const supplements=ref<Supplement[]>([])
function statusName(status:string){return labels[status] || status}
function formatTime(value:string){return value ? new Date(value).toLocaleString('zh-CN',{hour12:false}) : ''}
async function load(){ try { const page = await api<{items:Order[]}>('/orders'); orders.value = page.items; error.value = '' } catch(reason){error.value = reason instanceof Error ? reason.message : '订单加载失败'} }
async function show(id:number){try{[detail.value,supplements.value] = await Promise.all([api<Order>(`/orders/${id}`),api<Supplement[]>(`/orders/${id}/supplements`)]);detailOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error ? reason.message : '详情加载失败')}}
async function act(id:number,action:'confirm'|'cancel') {try{await ElMessageBox.confirm(action==='confirm'?'确认服务已完成？':'确定取消该预约？','请确认');await api(`/orders/${id}/${action}`,{method:'POST'});await load();ElMessage.success('操作成功')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
function settlementLabel(value:string){return ({WAITING_METHOD:'待选择方式',PROCESSING:'处理中',SETTLED:'已结算',FAILED:'交易失败或取消'} as Record<string,string>)[value]||value}
function attemptLabel(value:string){return ({UNREGISTERED:'待控制台登记',PROCESSING:'交易处理中',SUCCESS:'模拟交易成功',FAILED:'模拟交易失败',CANCELLED:'模拟交易已取消'} as Record<string,string>)[value]||value}
function supplementLabel(value:string){return ({PLANNED:'待派单',ASSIGNED:'待服务',IN_SERVICE:'服务中',SUBMITTED:'待用户确认',CONFIRMED:'已确认',CANCELLED:'已取消'} as Record<string,string>)[value]||value}
function feeLabel(value:string){return ({PENDING:'待确认',APPROVED:'已同意',REJECTED:'已拒绝'} as Record<string,string>)[value]||value}
async function openSettlement(id:number){try{settlementOrderId.value=id;settlement.value=await api<Settlement>(`/orders/${id}/settlement`);settlementOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'结算加载失败')}}
async function createAttempt(){try{await api(`/orders/${settlementOrderId.value}/settlement/payment-attempts`,{method:'POST'});await openSettlement(settlementOrderId.value);ElMessage.success('支付尝试已创建')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'创建失败')}}
async function sync(){try{settlement.value=await api<Settlement>(`/orders/${settlementOrderId.value}/settlement/sync`,{method:'POST'});ElMessage.success('交易状态已同步')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'查询失败')}}
function openReview(id:number){reviewOrderId.value=id;reviewStars.value=5;reviewContent.value='';reviewOpen.value=true}
async function submitReview(){try{await api(`/orders/${reviewOrderId.value}/review`,{method:'POST',body:JSON.stringify({stars:reviewStars.value,content:reviewContent.value})});reviewOpen.value=false;ElMessage.success('评价已提交')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'评价失败')}}
async function openFees(id:number){try{feesOrderId.value=id;fees.value=await api<Fee[]>(`/orders/${id}/fee-adjustments`);feesOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'费用加载失败')}}
async function decideFee(id:number,approve:boolean){try{await ElMessageBox.confirm(approve?'确认同意该异常费用并结案？':'确认拒绝该费用提案？','请确认');await api(`/orders/${feesOrderId.value}/fee-adjustments/${id}/${approve?'approve':'reject'}`,{method:'POST'});await openFees(feesOrderId.value);await load();ElMessage.success('处理结果已记录')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function openDispute(id:number){try{const result=await ElMessageBox.prompt('请说明争议事项，完成事实将保留。','发起事后争议',{inputValidator:value=>Boolean(value?.trim())||'必须填写争议原因'});await api(`/orders/${id}/disputes`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});ElMessage.success('争议已登记，等待管理员协调')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
onMounted(load)
</script>
<style scoped>.order-list{display:grid;gap:14px;margin-top:34px}.order-card{padding:24px 28px;display:flex;justify-content:space-between;align-items:center;gap:24px}.order-card h2{margin:8px 0;font-size:23px}.order-card p{margin:0}.order-actions{display:flex;align-items:center;gap:14px}.status{color:#137b60;font-weight:700}.detail p{display:flex;gap:20px;border-bottom:1px solid #edf1ee;padding:12px 0}.detail strong{min-width:90px}.attempt{display:grid;gap:8px;padding:16px;background:#f2f7f3;border-radius:12px;margin:16px 0;word-break:break-all}.attempt p{margin:0}.settlement-actions{display:flex;gap:12px}.form-error{color:#b34939}@media(max-width:680px){.order-card,.order-actions{align-items:flex-start;flex-direction:column}}</style>
